-- ========================================================
-- PathPilot Complete Supabase Seed Script
-- NMAMIT Autonomous Placement & Career Intelligence Gateway
-- 15 Engineering Branches, 120 Students, ERP Records & Drives
-- ========================================================

-- STEP 1: INSERT INSTITUTION (NMAMIT AUTONOMOUS)
-- Clean up any conflicting pre-existing institution with code 'NMAMIT' or slug 'nmamit-nitte'
DO $$
DECLARE
  existing_id uuid;
BEGIN
  SELECT id INTO existing_id FROM institutions WHERE (code = 'NMAMIT' OR slug = 'nmamit-nitte') AND id != '11111111-0000-0000-0000-000000000001' LIMIT 1;
  IF existing_id IS NOT NULL THEN
    UPDATE departments SET institution_id = '11111111-0000-0000-0000-000000000001' WHERE institution_id = existing_id;
    UPDATE profiles SET institution_id = '11111111-0000-0000-0000-000000000001' WHERE institution_id = existing_id;
    DELETE FROM institutions WHERE id = existing_id;
  END IF;
END $$;

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  short_name = EXCLUDED.short_name,
  code = EXCLUDED.code,
  slug = EXCLUDED.slug,
  website = EXCLUDED.website,
  is_active = EXCLUDED.is_active;

-- STEP 2: INSERT DEPARTMENTS (ALL 15 BRANCHES)
ON CONFLICT (institution_id, code) DO UPDATE SET name = EXCLUDED.name, total_intake = EXCLUDED.total_intake;

-- STEP 3: INSERT EVALUATOR & ADMINISTRATIVE PROFILES
ON CONFLICT (email) DO UPDATE SET full_name = EXCLUDED.full_name, role = EXCLUDED.role, designation = EXCLUDED.designation;

-- STEP 4: INSERT 120 STUDENT PROFILES
ON CONFLICT (id) DO UPDATE SET full_name = EXCLUDED.full_name, usn = EXCLUDED.usn;

-- STEP 5: INSERT 120 ACADEMIC RECORDS (CONTINEO ERP)
ON CONFLICT (id) DO UPDATE SET cgpa = EXCLUDED.cgpa, active_backlogs = EXCLUDED.active_backlogs;

-- STEP 6: INSERT STUDENT SKILL PASSPORTS
ON CONFLICT (id) DO UPDATE SET verification_badge = EXCLUDED.verification_badge;

-- STEP 7: INSERT RECRUITER COMPANIES
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;

-- STEP 8: INSERT CAMPUS PLACEMENT DRIVES
ON CONFLICT (id) DO UPDATE SET role_title = EXCLUDED.role_title;

-- STEP 9: INSERT PLACEMENT APPLICATIONS (MULTI-BRANCH SPREAD)
ON CONFLICT (id) DO UPDATE SET stage = EXCLUDED.stage;
